### Quick Refactor Example

Below is a minimal, “secure‑by‑default” version of `app.js` that addresses the points above while keeping the original functionality intact.

```js
// app.js – Hardened version
/* eslint-disable no-console */

const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const cors = require('cors');

const app = express();

// 1️⃣ Security headers
app.use(helmet());

// 2️⃣ Rate limiting (100 requests per minute per IP)
app.use(
  rateLimit({
    windowMs: 60_000,
    max: 100,
    standardHeaders: true,
    legacyHeaders: false,
  })
);

// 3️⃣ CORS – adjust allowed origins as needed
app.use(
  cors({
    origin: ['https://myapp.example.com'], // <-- change to your front‑end
    methods: ['GET'],
  })
);

// Health endpoint – no sensitive data
app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

// Example users endpoint (still static; in real life protect it!)
app.get('/users', (req, res) => {
  // In production you would protect this route with auth middleware
  res.json([
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ]);
});

/* 4️⃣ Central error handler – hides stack traces from clients */
app.use((err, _req, res, _next) => {
  console.error('Unhandled error:', err);
  res.status(500).json({ error: 'Internal Server Error' });
});

/* 5️⃣ Bind only to localhost for dev – change for production behind a proxy */
const PORT = process.env.PORT || 3000;
const HOST = process.env.NODE_ENV === 'production' ? undefined : '127.0.0.1';

app.listen(PORT, HOST, () => {
  console.log(`Server running on ${HOST ?? '0.0.0.0'}:${PORT}`);
});

module.exports = app;
```

**What you need to add to the repo**

1. `package.json` (with exact versions for `express`, `helmet`, `express-rate-limit`, `cors`, etc.).
2. Optional `npm audit` run to ensure no known vulnerabilities in those packages.
3. A `.env.example` file if you later introduce secrets (never commit real secrets).

