## How to Replace the Hard‑coded Values

Below is a minimal patch that:

1. **Reads the port and host from environment variables** (`process.env.PORT` and `process.env.HOST`).  
2. **Falls back to sensible defaults** for local development.  
3. **Loads the static user list from an external JSON file** (`users.json`). The path to that file can also be overridden with `USERS_FILE`.  
4. Keeps the original behaviour when the env vars are not set.

### 1. Add a JSON fixture for the users (optional but cleaner)

Create `data/users.json`:

```json
[
  { "id": 1, "name": "Alice", "email": "alice@example.com" },
  { "id": 2, "name": "Bob",   "email": "bob@example.com" }
]
```

### 2. Updated `app.js`

```js
// app.js – Hardened & configurable version
/* eslint-disable no-console */

const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const cors = require('cors');
const path = require('path');
const fs = require('fs');

const app = express();

/* ---------- 1️⃣ Security middleware (unchanged) ---------- */
app.use(helmet());

app.use(
  rateLimit({
    windowMs: 60_000,
    max: 100,
    standardHeaders: true,
    legacyHeaders: false,
  })
);

app.use(
  cors({
    origin: ['https://myapp.example.com'], // adjust as needed
    methods: ['GET'],
  })
);

/* ---------- 2️⃣ Configurable values ---------- */
const PORT = process.env.PORT ? Number(process.env.PORT) : 3000;
const HOST = process.env.HOST || (process.env.NODE_ENV === 'production' ? undefined : '127.0.0.1');

/* Path to the users fixture – can be overridden */
const USERS_FILE = process.env.USERS_FILE || path.resolve(__dirname, 'data', 'users.json');

/* Load users once at startup (sync is fine for tiny fixture) */
let users = [];
try {
  const raw = fs.readFileSync(USERS_FILE, 'utf8');
  users = JSON.parse(raw);
} catch (e) {
  console.warn('⚠️ Could not load users file:', e.message);
}

/* ---------- 3️⃣ Routes ---------- */
app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

app.get('/users', (req, res) => {
  // In production you would protect this route and fetch from a DB.
  res.json(users);
});

/* ---------- 4️⃣ Central error handling ---------- */
app.use((err, _req, res, _next) => {
  console.error('Unhandled error:', err);
  res.status(500).json({ error: 'Internal Server Error' });
});

/* ---------- 5️⃣ Server start ---------- */
app.listen(PORT, HOST, () => {
  const bind = HOST ? `${HOST}:${PORT}` : `:${PORT}`;
  console.log(`🚀 Server listening on ${bind}`);
});

module.exports = app;
