## 2. Quick verification script (Node.js)

Create a file `scripts/check-env-format.js` (you can run it with `node scripts/check-env-format.js`):

```js
#!/usr/bin/env node
/* eslint-disable no-console */

const fs = require('fs');
const path = require('path');

// Load .env if you use dotenv (optional)
require('dotenv').config();

const patterns = {
  PORT:        /^[0-9]{1,5}$/,
  HOST:        /^(?:((25[0-5]|2[0-4]\d|[01]?\d?\d)(\.|$)){4}|(\[?[0-9a-fA-F:]+\]?)|(?=.{1,253}$)(?!-)[A-Za-z0-9-]{1,63}(?<!-)(\.(?!-)[A-Za-z0-9-]{1,63}(?<!-))*$)$/,
  USERS_FILE: /^(\/|\.\/|\.\\)?([A-Za-z0-9._-]+\/)*[A-Za-z0-9._-]+\.(json|js|txt|yml|yaml)$/,
  NODE_ENV:    /^(development|production|test)$/,
};

function validate(name, value) {
  const regex = patterns[name];
  if (!regex) return; // unknown var – ignore
  if (value == null) {
    console.warn(`⚠️  ${name} is not set`);
    return;
  }

  if (!regex.test(value)) {
    console.error(`❌  ${name} = "${value}"  ❌  does NOT match expected pattern`);
  } else if (name === 'PORT' && Number(value) > 65535) {
    console.error(`❌  ${name} = "${value}"  ❌  exceeds max TCP port (65535)`);
  } else {
    console.log(`✅  ${name} = "${value}"`);
  }
}

// List of variables we care about
['PORT', 'HOST', 'USERS_FILE', 'NODE_ENV'].forEach(v => validate(v, process.env[v]));
```

Make it executable (`chmod +x scripts/check-env-format.js`) and run it after sourcing your `.env` (or after `export`‑ing the variables). It will report any mismatches.

